use vstd::prelude::*;

verus! {

    // Find an index of a maximum element in a non‐empty slice of i32.
    // The result is within bounds, and the element at that index
    // is ≥ every element in the slice.
    fn find_max(a: &[i32]) -> usize
        requires
            a.len() > 0,
        ensures
            // result is a valid index
            result < a.len(),
        ensures
            // a[result] is a maximum
            forall |i: usize| i < a.len() ==> a[result] >= a[i],
    {
        // best = index of max in prefix a[0..i)
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant
                // loop index bounds
                1 <= i <= a.len(),
                // best points inside prefix
                best < i,
                // best is max among a[0..i)
                forall |j: usize| j < i ==> a[best] >= a[j],
            decreases
                a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }
}

